// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceRtcSignaler {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceRtcSignaler = UniffiVTableCallbackInterfaceRtcSignaler(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeRtcSignaler.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface RtcSignaler: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeRtcSignaler.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface RtcSignaler: handle missing in uniffiClone")
            }
        },
        signal: { (
            uniffiHandle: UInt64,
            offerJson: RustBuffer,
            reply: UInt64,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeRtcSignaler.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.signal(
                     offerJson: try FfiConverterString.lift(offerJson),
                     reply: try FfiConverterTypeSignalReply_lift(reply)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceRtcSignaler> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceRtcSignaler>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitRtcSignaler() {
    uniffi_uu_link_ffi_fn_init_callback_vtable_rtcsignaler(UniffiCallbackInterfaceRtcSignaler.vtablePtr)
}

