/**
 * The speed test's result (`LinkSession.probe`, docs/LINK.md「测速」). Rates in Mbit/s, times in ms; nil = not
 * measured.
 */
public struct ProbeReport: Equatable, Hashable {
    public var transport: Transport
    public var path: PathKind
    public var iface: Iface
    public var durationMs: UInt64
    /**
     * The idle path's RTT (lowest of the 10 s before), and the RTT under the test's load.
     */
    public var rttIdleMs: Double?
    public var rttP50Ms: Double?
    public var rttP90Ms: Double?
    /**
     * Frames delivered; their payload rate over the whole test, the best second, the last two seconds.
     */
    public var frames: UInt64
    public var receivedMbps: Double?
    public var peakMbps: Double?
    public var finalMbps: Double?
    public var finalFps: Double?
    /**
     * Media datagrams lost before FEC (%), and what FEC / NACK got back.
     */
    public var lossPct: Double?
    public var fecRecovered: UInt64
    public var nackRecovered: UInt64
    public var lostFrames: UInt64
    public var skippedFrames: UInt64
    public var freezes: UInt64
    public var freezeMs: UInt64
    public var server: ProbeServerReport?
    /**
     * All of the above as JSON (camelCase, the shape docs/LINK.md「测速」 lists).
     */
    public var json: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(transport: Transport, path: PathKind, iface: Iface, durationMs: UInt64, 
        /**
         * The idle path's RTT (lowest of the 10 s before), and the RTT under the test's load.
         */rttIdleMs: Double?, rttP50Ms: Double?, rttP90Ms: Double?, 
        /**
         * Frames delivered; their payload rate over the whole test, the best second, the last two seconds.
         */frames: UInt64, receivedMbps: Double?, peakMbps: Double?, finalMbps: Double?, finalFps: Double?, 
        /**
         * Media datagrams lost before FEC (%), and what FEC / NACK got back.
         */lossPct: Double?, fecRecovered: UInt64, nackRecovered: UInt64, lostFrames: UInt64, skippedFrames: UInt64, freezes: UInt64, freezeMs: UInt64, server: ProbeServerReport?, 
        /**
         * All of the above as JSON (camelCase, the shape docs/LINK.md「测速」 lists).
         */json: String) {
        self.transport = transport
        self.path = path
        self.iface = iface
        self.durationMs = durationMs
        self.rttIdleMs = rttIdleMs
        self.rttP50Ms = rttP50Ms
        self.rttP90Ms = rttP90Ms
        self.frames = frames
        self.receivedMbps = receivedMbps
        self.peakMbps = peakMbps
        self.finalMbps = finalMbps
        self.finalFps = finalFps
        self.lossPct = lossPct
        self.fecRecovered = fecRecovered
        self.nackRecovered = nackRecovered
        self.lostFrames = lostFrames
        self.skippedFrames = skippedFrames
        self.freezes = freezes
        self.freezeMs = freezeMs
        self.server = server
        self.json = json
    }

    

    
}

