        self.`open` = `open`
        self.overQueue = overQueue
        self.overSpace = overSpace
        self.ownQueued = ownQueued
        self.transportQueued = transportQueued
        self.transportSpace = transportSpace
        self.budget = budget
        self.limit = limit
        self.estimate = estimate
        self.targetBps = targetBps
        self.pacingBps = pacingBps
    }

    

    
}

