/**
 * What the client's media layer delivers.
 */

public enum ClientMediaEvent: Equatable, Hashable {
    
    case frame(frame: VideoFrame
    )
    case audio(packet: AudioPacket
    )
    /**
     * A newer cursor position (JSON `{x,y,visible,shapeId}`).
     */
    case cursor(stream: UInt8, cseq: UInt32, json: Data
    )
    /**
     * Every discrete input event up to `through` arrived.
     */
    case inputAcked(through: UInt32
    )
    /**
     * A discrete input event was not acknowledged within 2 s and was dropped.
     */
    case inputFailed(seq: UInt32
    )





}

#if compiler(>=6)
extension ClientMediaEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeClientMediaEvent: FfiConverterRustBuffer {
    typealias SwiftType = ClientMediaEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ClientMediaEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .frame(frame: try FfiConverterTypeVideoFrame.read(from: &buf)
        )
        
        case 2: return .audio(packet: try FfiConverterTypeAudioPacket.read(from: &buf)
        )
        
        case 3: return .cursor(stream: try FfiConverterUInt8.read(from: &buf), cseq: try FfiConverterUInt32.read(from: &buf), json: try FfiConverterData.read(from: &buf)
        )
        
        case 4: return .inputAcked(through: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 5: return .inputFailed(seq: try FfiConverterUInt32.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ClientMediaEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .frame(frame):
            writeInt(&buf, Int32(1))
            FfiConverterTypeVideoFrame.write(frame, into: &buf)
            
        
        case let .audio(packet):
            writeInt(&buf, Int32(2))
            FfiConverterTypeAudioPacket.write(packet, into: &buf)
            
        
        case let .cursor(stream,cseq,json):
            writeInt(&buf, Int32(3))
            FfiConverterUInt8.write(stream, into: &buf)
            FfiConverterUInt32.write(cseq, into: &buf)
            FfiConverterData.write(json, into: &buf)
            
        
        case let .inputAcked(through):
            writeInt(&buf, Int32(4))
            FfiConverterUInt32.write(through, into: &buf)
            
        
        case let .inputFailed(seq):
            writeInt(&buf, Int32(5))
            FfiConverterUInt32.write(seq, into: &buf)
            
        }
    }
}


