enum LinkError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidArgument(message: String
    )
    case Bind(message: String
    )
    case Connect(message: String
    )
    case Timeout(message: String
    )
    case Denied(code: DenyCode, message: String
    )
    case Protocol(message: String
    )
    case Closed(message: String
    )
    case Binding(message: String
    )
    case Datagram(message: String
    )
    case Io(message: String
    )
    case Media(message: String
    )
    case Internal(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

