public struct FfiConverterTypeLinkError: FfiConverterRustBuffer {
    typealias SwiftType = LinkError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LinkError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidArgument(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Bind(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Connect(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Timeout(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Denied(
            code: try FfiConverterTypeDenyCode.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Protocol(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Closed(
            message: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Binding(
            message: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Datagram(
            message: try FfiConverterString.read(from: &buf)
            )
        case 10: return .Io(
            message: try FfiConverterString.read(from: &buf)
            )
        case 11: return .Media(
            message: try FfiConverterString.read(from: &buf)
            )
        case 12: return .Internal(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LinkError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidArgument(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Bind(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Connect(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Timeout(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Denied(code,message):
            writeInt(&buf, Int32(5))
            FfiConverterTypeDenyCode.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Protocol(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Closed(message):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Binding(message):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Datagram(message):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Io(message):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Media(message):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Internal(message):
            writeInt(&buf, Int32(12))
