/**
 * What the server's media layer reports.
 */

public enum ServerMediaEvent: Equatable, Hashable {
    
    /**
     * Set the encoder to `encoder_bps` (per video stream).
     */
    case targetBitrate(targetBps: UInt64, encoderBps: UInt64
    )
    /**
     * The client decoded `frame` (LTR acknowledgement).
     */
    case frameDelivered(stream: UInt8, frame: UInt32
    )
    /**
     * Next frame: a recovery frame on the newest acknowledged LTR, or a key frame.
     */
    case recoveryNeeded(stream: UInt8, lastDelivered: UInt32?
    )
    case keyframeNeeded(stream: UInt8
    )
    case input(event: InputEvent
    )





}

#if compiler(>=6)
extension ServerMediaEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeServerMediaEvent: FfiConverterRustBuffer {
    typealias SwiftType = ServerMediaEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ServerMediaEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .targetBitrate(targetBps: try FfiConverterUInt64.read(from: &buf), encoderBps: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 2: return .frameDelivered(stream: try FfiConverterUInt8.read(from: &buf), frame: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 3: return .recoveryNeeded(stream: try FfiConverterUInt8.read(from: &buf), lastDelivered: try FfiConverterOptionUInt32.read(from: &buf)
        )
        
        case 4: return .keyframeNeeded(stream: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 5: return .input(event: try FfiConverterTypeInputEvent.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ServerMediaEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .targetBitrate(targetBps,encoderBps):
            writeInt(&buf, Int32(1))
            FfiConverterUInt64.write(targetBps, into: &buf)
            FfiConverterUInt64.write(encoderBps, into: &buf)
            
        
        case let .frameDelivered(stream,frame):
            writeInt(&buf, Int32(2))
            FfiConverterUInt8.write(stream, into: &buf)
            FfiConverterUInt32.write(frame, into: &buf)
            
        
        case let .recoveryNeeded(stream,lastDelivered):
            writeInt(&buf, Int32(3))
            FfiConverterUInt8.write(stream, into: &buf)
            FfiConverterOptionUInt32.write(lastDelivered, into: &buf)
            
        
        case let .keyframeNeeded(stream):
            writeInt(&buf, Int32(4))
            FfiConverterUInt8.write(stream, into: &buf)
            
        
        case let .input(event):
            writeInt(&buf, Int32(5))
            FfiConverterTypeInputEvent.write(event, into: &buf)
            
        }
    }
}


